schema:
CREATE TABLE Actual_Order_Products (
  actual_order_id bigint,
  product_id bigint
);
CREATE TABLE Actual_Orders (
  actual_order_id bigint,
  order_status_code text,
  regular_order_id bigint,
  actual_order_date text
);
CREATE TABLE Addresses (
  address_id bigint,
  address_details text,
  city text,
  zip_postcode text,
  state_province_county text,
  country text,
  Addresses_description text,
  address_details_embedding vector
);
CREATE TABLE Customer_Addresses (
  customer_id bigint,
  address_id bigint,
  date_from text,
  address_type text,
  date_to text
);
CREATE TABLE Customers (
  customer_id bigint,
  payment_method text,
  customer_name text,
  customer_phone text,
  customer_email text,
  date_became_customer text,
  Customers_description text
);
CREATE TABLE Delivery_Route_Locations (
  location_code text,
  route_id bigint,
  location_address_id bigint,
  location_name text
);
CREATE TABLE Delivery_Routes (
  route_id bigint,
  route_name text,
  other_route_details text,
  Delivery_Routes_description text,
  other_route_details_embedding vector
);
CREATE TABLE Employees (
  employee_id bigint,
  employee_address_id bigint,
  employee_name text,
  employee_phone text,
  Employees_description text
);
CREATE TABLE Order_Deliveries (
  location_code text,
  actual_order_id bigint,
  delivery_status_code text,
  driver_employee_id bigint,
  truck_id bigint,
  delivery_date text
);
CREATE TABLE Products (
  product_id bigint,
  product_name text,
  product_price double precision,
  product_description text,
  product_description_embedding vector
);
CREATE TABLE Regular_Order_Products (
  regular_order_id bigint,
  product_id bigint
);
CREATE TABLE Regular_Orders (
  regular_order_id bigint,
  distributer_id bigint
);
CREATE TABLE Trucks (
  truck_id bigint,
  truck_licence_number text,
  truck_details text,
  Trucks_description text
);

